contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund)); require(fund <= 1000000000000000000000000000000);
        require(address(this).balance >= fund);
        uint256 valueBefore = c.value(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getTokens{value: fund}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        assert(!reverted == (c.value() == (valueBefore / 100000) * 99999));
    }

    receive() external payable {}
}

