// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 fund) internal {
        fund = bound(fund, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        uint256 valueBefore;
        try c.value() returns (uint256 __r) { valueBefore = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: fund}() { reverted = false; } catch { reverted = true; }
        assertTrue(!reverted == (c.value() == (valueBefore / 100000) * 99999));
    }

    function testFuzz_run(uint256 fund) public {
        _run(fund);
    }

    receive() external payable {}
}
